import warnings
warnings.simplefilter("ignore")
import numpy as np
from sktime.benchmarking.results import RAMResults
from sktime.benchmarking.metrics import PairwiseMetric
from sktime.benchmarking.evaluation import Evaluator
from sktime.exceptions import NotEvaluatedError

class CV:
    def __init__(self, n=2): self.n = n
    def get_n_splits(self, *a, **k): return self.n

def mae(y_true, y_pred):
    return float(np.mean(np.abs(np.asarray(y_true)-np.asarray(y_pred))))

res = RAMResults(); res.cv = CV(2)
yt = np.array([1.0,2.0])
# fold 0: error 0 ; fold 1: error 3
res.save_predictions("s1","d1", yt, np.array([1.0,2.0]), None, np.arange(2), 0, "test")
res.save_predictions("s1","d1", yt, np.array([4.0,5.0]), None, np.arange(2), 1, "test")
res.save_predictions("s1","d1", yt, np.array([0.0,0.0]), None, np.arange(2), 0, "train")
ev = Evaluator(res)
print("props before:", end=" ")
try: ev.metrics
except NotEvaluatedError as e: print("NotEvaluatedError", str(e)[:40])
print(ev.evaluate(metric=PairwiseMetric(func=mae, name="mae"), cv_fold=0))
ev2 = Evaluator(res)
print(ev2.evaluate(metric=PairwiseMetric(func=mae, name="mae"), cv_fold="all"))
ev3 = Evaluator(res)
print(ev3.evaluate(metric=PairwiseMetric(func=mae, name="mae"), train_or_test="train"))
for bad in [-1, "bad", 1.5]:
    try: ev.evaluate(metric=PairwiseMetric(func=mae), cv_fold=bad)
    except ValueError as e: print("bad cv_fold", repr(bad), type(e).__name__, str(e)[:60])
res0 = RAMResults(); res0.cv = CV(0)
evx = Evaluator(res0)
try: evx.evaluate(metric=PairwiseMetric(func=mae), cv_fold="all")
except ValueError as e: print("zero splits ValueError:", repr(str(e)))
try: Evaluator("notresults")
except ValueError as e: print("bad results:", str(e))
print("run time no timings:", )
try: print(ev.fit_runtime())
except Exception as e: print("fit_runtime err", type(e).__name__, e)
try: ev.rank(ascending="yes")
except ValueError as e: print("rank ascending err:", str(e)[:60])
try: ev.rank("nope")
except ValueError as e: print("rank metric err:", str(e)[:60])
EOF
