from sktime.benchmarking.results import RAMResults
from sktime.benchmarking.metrics import PairwiseMetric
from sktime.benchmarking.evaluation import Evaluator

class CV:
    def get_n_splits(self, *a, **k): return 2
def mae(yt, yp): return float(np.mean(np.abs(np.asarray(yt)-np.asarray(yp))))
res = RAMResults(); res.cv = CV()
yt = np.array([1.0,2.0,3.0,4.0])
preds = {"s1": np.array([1.0,2.0,3.0,5.0]), "s2": np.array([2.0,2.0,2.0,2.0]), "s3": np.array([1.0,1.0,1.0,1.0])}
