import numpy as np, pandas as pd
import sktime.libs.kronos.kronos as k

class Stub:
    def to(self, d): return self

class W:
    def __init__(self, a): self.a=np.asarray(a)
    def to(self, d): return self
    def numpy(self): return self.a
    def __array__(self, dtype=None): return self.a

class T:
    @staticmethod
    def from_numpy(a): return W(a)

calls=[]
def fake(tokenizer, model, x, x_stamp, y_stamp, max_context, pred_len, clip, T_, top_k, top_p, sample_count, verbose):
    xa = np.asarray(x)
    calls.append(dict(x=xa, xs=np.asarray(x_stamp), ys=np.asarray(y_stamp), pred_len=pred_len, clip=clip))
    B = xa.shape[0]
    return np.full((B, xa.shape[1]+pred_len, xa.shape[2]), 0.5)

k.auto_regressive_inference = fake
k.torch = T

p = k.KronosPredictor(Stub(), Stub(), device="cpu", max_context=8, clip=3)
idx = pd.date_range("2024-01-01", periods=6, freq="h")
df = pd.DataFrame(np.arange(24, dtype=float).reshape(6,4), columns=["open","high","low","close"], index=idx)
sid = pd.Series(pd.date_range("2024-01-02", periods=3, freq="h"))
out = p.predict(df, pd.Series(idx), sid, pred_len=3, verbose=False)
print(out)
print(calls[0]["x"].shape, calls[0]["xs"].shape, calls[0]["ys"].shape)
print(calls[0]["x"][0][:, 4])
