import sktime.libs.kronos.kronos as k

class Stub:
    def to(self, d): return self
class W:
    def __init__(self, a): self.a=np.asarray(a)
    def to(self, d): return self
    def __array__(self, dtype=None): return self.a
class T:
    @staticmethod
    def from_numpy(a): return W(a)
recs=[]
def fake(tokenizer, model, x, x_stamp, y_stamp, max_context, pred_len, clip, T_, top_k, top_p, sample_count, verbose):
    recs.append((np.asarray(x), np.asarray(x_stamp), np.asarray(y_stamp), pred_len))
