    p.predict_batch([df1], [pd.Series(idx1)], [ys[0]], 3)
except ValueError as e:
    print("ERR3", e)
try:
    p.predict_batch([df1, df2.drop(columns="close")], [pd.Series(idx1), pd.Series(idx2)], ys, 2)
except ValueError as e:
    print("ERR4", e)
try:
    p.predict_batch([df1, df2.iloc[:5]], [pd.Series(idx1), pd.Series(idx2)[:5]], ys, 2)
except ValueError as e:
    print("ERR5", e)
