    n_rows=8,
    scale=1.0,
    with_volume=True,
    with_amount=True,
    start="2024-01-01",
):
    index = pd.date_range(start, periods=n_rows, freq="h")
    base = np.arange(n_rows, dtype=float)
    data = {
        "open": scale * (10.0 + base),
        "high": scale * (11.0 + base),
        "low": scale * (9.0 + base),
        "close": scale * (10.5 + base),
    }
    if with_volume:
        data["volume"] = scale * (100.0 + 10.0 * base)
        if with_amount:
            data["amount"] = scale * (1000.0 + 100.0 * base)
    return pd.DataFrame(data, index=index)


