def _normalize(raw, clip):
    raw = np.asarray(raw, dtype=np.float32)
    mean, std = raw.mean(axis=0), raw.std(axis=0)
    return mean, std, np.clip((raw - mean) / (std + 1e-5), -clip, clip)


