        self.indices = indices


class _NumpyTensor:
    """Very small subset of ``torch.Tensor`` semantics backed by numpy."""

    # -- construction ------------------------------------------------------
    def __init__(self, data, dtype=None, device=None, requires_grad=False):
        if isinstance(data, _NumpyTensor):
            arr = data._a
        else:
            arr = data
        arr = np.asarray(arr)
        if isinstance(dtype, _DType):
            arr = arr.astype(dtype.np_dtype)
        self._a = arr
        self._device = device
        self.requires_grad = bool(requires_grad)

    # -- basic attributes --------------------------------------------------
    @property
    def shape(self):
        return tuple(self._a.shape)

    @property
    def ndim(self):
        return self._a.ndim

    @property
    def dtype(self):
        kind = self._a.dtype
        if kind == np.bool_:
            return _BOOL
        if np.issubdtype(kind, np.integer):
            return _LONG
        if kind == np.float64:
            return _FLOAT64
        return _FLOAT32

    @property
    def device(self):
        return self._device

    def dim(self):
        return self._a.ndim

    def numel(self):
        return int(self._a.size)

    def size(self, dim=None):
        if dim is None:
            return tuple(self._a.shape)
        return int(self._a.shape[dim])

    def __len__(self):
        return len(self._a)

    def __repr__(self):
        return f"tensor({self._a!r})"

    # -- conversions -------------------------------------------------------
    def numpy(self):
        return self._a

    def detach(self):
        return self

    def cpu(self):
        return self

    def clone(self):
        return _NumpyTensor(self._a.copy(), device=self._device)

    def to(self, *args, **kwargs):
        dtype = kwargs.get("dtype", None)
        for arg in args:
            if isinstance(arg, _DType):
                dtype = arg
        device = kwargs.get("device", self._device)
        return _NumpyTensor(self._a, dtype=dtype, device=device)

    def bool(self):
        return _NumpyTensor(self._a.astype(np.bool_))

    def float(self):
        return _NumpyTensor(self._a.astype(np.float32))

    def long(self):
        return _NumpyTensor(self._a.astype(np.int64))

    def item(self):
        return self._a.item()

    def type(self, dtype):
        return _NumpyTensor(self._a, dtype=dtype)

    # -- shape manipulation ------------------------------------------------
    def view(self, *shape):
        if len(shape) == 1 and isinstance(shape[0], (tuple, list)):
            shape = tuple(shape[0])
