    def transpose(self, dim0, dim1):
        axes = list(range(self._a.ndim))
        axes[dim0], axes[dim1] = axes[dim1], axes[dim0]
        return _NumpyTensor(np.transpose(self._a, axes), device=self._device)

    def contiguous(self):
        return _NumpyTensor(np.ascontiguousarray(self._a), device=self._device)

    def unsqueeze(self, dim):
