    def squeeze(self, dim=None):
        if dim is None:
            return _NumpyTensor(np.squeeze(self._a), device=self._device)
        return _NumpyTensor(np.squeeze(self._a, axis=dim), device=self._device)

    def flatten(self):
        return _NumpyTensor(self._a.reshape(-1), device=self._device)

    def unfold(self, dimension, size, step):
        dim = dimension if dimension >= 0 else self._a.ndim + dimension
        moved = np.moveaxis(self._a, dim, -1)
        windows = np.lib.stride_tricks.sliding_window_view(moved, size, axis=-1)
        windows = windows[..., ::step, :]
        out = np.moveaxis(windows, -2, dim)
        return _NumpyTensor(np.ascontiguousarray(out), device=self._device)

    # -- reductions --------------------------------------------------------
    def mean(self, dim=None, keepdim=False):
        if dim is None:
            return _NumpyTensor(np.mean(self._a), device=self._device)
        return _NumpyTensor(
            np.mean(self._a, axis=dim, keepdims=keepdim), device=self._device
        )

    def sum(self, dim=None, keepdim=False):
        if dim is None:
            return _NumpyTensor(np.sum(self._a), device=self._device)
        return _NumpyTensor(
            np.sum(self._a, axis=dim, keepdims=keepdim), device=self._device
        )

    def abs(self):
        return _NumpyTensor(np.abs(self._a), device=self._device)

    def median(self, dim=None, keepdim=False):
