        return _NumpyTensor(
            np.ones(size, dtype=dtype.np_dtype), device=kwargs.get("device")
        )

    def zeros_like(tensor, **kwargs):
        tensor = _unwrap(tensor)
        return _NumpyTensor(np.zeros_like(tensor), device=kwargs.get("device"))

    def ones_like(tensor, **kwargs):
        tensor = _unwrap(tensor)
        return _NumpyTensor(np.ones_like(tensor), device=kwargs.get("device"))

    def full(size, fill_value, **kwargs):
        dtype = kwargs.get("dtype") or _FLOAT32
        return _NumpyTensor(
