GLOBAL_BATCH = PER_CORE_BATCH * NUM_DEVICES
# length of the fake decoder output = context + horizon (as the real model does
# when ``return_forecast_on_context=True``)
DECODER_LEN = CONTEXT_LEN + HORIZON_LEN
# length of the forecast returned by ``TimesFm.forecast`` in default mode
FORECAST_LEN = DECODER_LEN - (CONTEXT_LEN - INPUT_PATCH_LEN)


