class _FakeEinshape:
    """Stand-in for ``einshape``, only supporting the patterns the target uses."""

    def jax_einshape(self, pattern, x, **kwargs):
        d = kwargs.get("d")
        arr = np.asarray(x)
        if pattern == "(db)...->db...":
            return arr.reshape((d, arr.shape[0] // d) + arr.shape[1:])
        if pattern == "db...->(db)...":
            return arr.reshape((arr.shape[0] * arr.shape[1],) + arr.shape[2:])
        raise AssertionError(f"unsupported einshape pattern: {pattern}")


