def _fake_make_future_dataframe(uids, last_times, h, freq):
    """Deterministic stand-in for ``utilsforecast``'s ``make_future_dataframe``."""
    uids = list(uids)
    last_times = list(np.asarray(pd.Series(last_times).to_numpy()))
    frames = []
    for uid, last_time in zip(uids, last_times):
        ds = pd.date_range(start=pd.Timestamp(last_time), periods=h + 1, freq=freq)[1:]
        frames.append(pd.DataFrame({"unique_id": [uid] * h, "ds": ds}))
    return pd.concat(frames, ignore_index=True)


def _make_decode(stat="mean", offset=0.0, channels=3):
    """Return a deterministic substitute for the pmapped model decoder.

    The decoder summarises the received context (mean or last value), subtracts
    ``offset`` and broadcasts the result over context + horizon, mimicking the
    shape contract of the real decoder.  Channel 0 of the full output is the
    point forecast, channels ``1 + i`` are the quantiles, i.e. ``channels`` must
    be ``1 + len(quantiles)``.
    """
    calls = []

    def _decode(nested):
        calls.append(nested)
        input_ts = np.asarray(nested["input_ts"], dtype=float)
        _, _, ctx = input_ts.shape
        if stat == "mean":
            per_series = input_ts.mean(axis=-1)
        elif stat == "last":
            per_series = input_ts[:, :, -1]
        else:  # pragma: no cover - guards against typos in tests
            raise AssertionError(f"unknown stat: {stat}")
        value = per_series - offset
        mean_output = np.repeat(value[:, :, None], ctx + HORIZON_LEN, axis=2)
        full_output = np.stack(
            [mean_output + float(i) for i in range(channels)], axis=-1
        )
        return mean_output, full_output

    _decode.calls = calls
    return _decode


