def test_moving_average_window_of_one_is_identity():
    arr = np.array([3.0, -1.0, 0.0, 7.5])
    smoothed, residual = moving_average(arr, 1)
    np.testing.assert_allclose(smoothed, arr)
    np.testing.assert_allclose(residual, np.zeros_like(arr))


def test_moving_average_known_values():
    arr = np.array([1.0, 2.0, 3.0, 4.0])
    smoothed, residual = moving_average(arr, 2)
    np.testing.assert_allclose(smoothed, [0.5, 1.5, 2.5, 3.5])
    np.testing.assert_allclose(residual, [0.5, 0.5, 0.5, 0.5])


def test_moving_average_outputs_have_input_length():
    arr = np.arange(6, dtype=float)
    for window in (1, 2, 5, 6):
        smoothed, residual = moving_average(arr, window)
        assert len(smoothed) == len(arr)
        assert len(residual) == len(arr)


def test_moving_average_decomposition_reconstructs_input():
    arr = np.array([5.0, 3.0, 9.0, -2.0, 4.0, 4.5, 1.0])
    smoothed, residual = moving_average(arr, 3)
    np.testing.assert_allclose(np.asarray(smoothed) + np.asarray(residual), arr)


