{"command": "cat > /tmp/mutplug.py <<'EOF'
import os
import math
import torch
from einops import rearrange
from sktime.libs.uni2ts import forecast as F

MUT = os.environ.get("MUT", "")

if MUT == "ceil":
    F.MoiraiForecast.context_token_length = lambda self, p: self.hparams.context_length // p
elif MUT == "truncate":
    def _fmt(self, patch_size, preds, target_dim):
        start = target_dim * self.context_token_length(patch_size)
        end = start + target_dim * self.prediction_token_length(patch_size)
        preds = preds[..., start:end, :patch_size]
        preds = rearrange(
            preds, "sample ... (dim seq) patch -> ... sample (seq patch) dim", dim=target_dim
        )
        return preds.squeeze(-1)
    F.MoiraiForecast._format_preds = _fmt
elif MUT == "past_length":
    F.MoiraiForecast.past_length = property(lambda self: self.hparams.context_length)
elif MUT == "argmax":
    src = open(F.__file__).read()
    # patch forward to use argmax
    orig = F.MoiraiForecast.forward
    def fwd(self, *args, **kwargs):
        orig_forward = orig
        return orig_forward(self, *args, **kwargs)
elif MUT == "sum":
    def reduce_loss(self, loss, prediction_mask, observed_mask, sample_id, variate_id):
        id_mask = torch.logical_and(
            torch.eq(sample_id.unsqueeze(-1), sample_id.unsqueeze(-2)),
            torch.eq(variate_id.unsqueeze(-1), variate_id.unsqueeze(-2)),
        )
        mask = prediction_mask.unsqueeze(-1) * observed_mask
        return (loss * mask).sum(dim=(-1, -2))
    F.SampleNLLLoss.reduce_loss = reduce_loss
elif MUT == "padright":
    orig_pad = F.MoiraiForecast._patched_seq_pad
    @staticmethod
    def patched(patch_size, x, dim, left=True, value=None):
        return orig_pad(patch_size, x, dim, left=not left, value=value)
    F.MoiraiForecast._patched_seq_pad = patched
EOF
cd /testbed && for m in ceil truncate past_length sum padright; do echo "== $m"; MUT=$m PYTHONPATH=/tmp python -m pytest tests/sktime/libs/uni2ts/test_forecast.py -q --noconftest -o addopts="" -p no:randomly -p mutplug 2>&1 | tail -2; done"}

